class MuluMascot{constructor(t={}){this.containerId=t.containerId||"mulu-root",this.interactive=!1!==t.interactive,this.tourSteps=[{text:"Hi! I'm Mulu, your STEMulus AI Guide! Welcome to your Portal!",highlight:null},{text:"Track your classes, logs, and student performance here.",highlight:".dash-card, .data-panel, main"},{text:"Floating tools are available anytime for quick actions!",highlight:".pill-toolbar, .portal-nav"},{text:"Click me anytime for tips. Have fun learning!",highlight:"#mulu-character"}],this.currentStep=0,this.autoHideTimer=null,this.init()}init(){this.injectStyles(),this.render(),this.interactive&&(this.bindEvents(),this.checkFirstTimeTour(),this.scheduleAutoHide())}injectStyles(){if(document.getElementById("mulu-styles"))return;const t=document.createElement("style");t.id="mulu-styles",t.textContent="\n            .mulu-floating-widget {\n                position: fixed;\n                bottom: 20px;\n                right: 20px;\n                z-index: 9999;\n                display: flex;\n                flex-direction: column;\n                align-items: flex-end;\n                pointer-events: none;\n                font-family: 'Nunito', sans-serif;\n            }\n\n            .mulu-bubble {\n                background: #FFFFFF;\n                color: #1E293B;\n                padding: 10px 14px;\n                border-radius: 16px 16px 4px 16px;\n                box-shadow: 0 8px 24px rgba(0,0,0,0.12);\n                font-size: 12px;\n                font-weight: 700;\n                margin-bottom: 8px;\n                max-width: 210px;\n                pointer-events: auto;\n                animation: muluPop 0.25s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n                border: 1px solid #E2E8F0;\n                line-height: 1.35;\n                position: relative;\n            }\n\n            .mulu-close-btn {\n                position: absolute;\n                top: -6px;\n                right: -6px;\n                width: 18px;\n                height: 18px;\n                background: #F1F5F9;\n                color: #64748B;\n                border: 1px solid #CBD5E1;\n                border-radius: 50%;\n                font-size: 11px;\n                font-weight: 800;\n                display: flex;\n                align-items: center;\n                justify-content: center;\n                cursor: pointer;\n                line-height: 1;\n            }\n            .mulu-close-btn:hover { background: #EF4444; color: #FFFFFF; border-color: #EF4444; }\n\n            .mulu-tour-actions {\n                display: flex;\n                justify-content: space-between;\n                align-items: center;\n                margin-top: 8px;\n                padding-top: 6px;\n                border-top: 1px solid #F1F5F9;\n            }\n\n            .mulu-btn {\n                background: #4FC3F7;\n                color: white;\n                border: none;\n                padding: 4px 10px;\n                border-radius: 8px;\n                font-size: 10px;\n                font-weight: 800;\n                cursor: pointer;\n                transition: transform 0.15s, background 0.15s;\n            }\n            .mulu-btn:hover { background: #0288D1; transform: scale(1.04); }\n\n            .mulu-btn-sec {\n                background: none;\n                border: none;\n                color: #94A3B8;\n                font-size: 10px;\n                font-weight: 700;\n                cursor: pointer;\n            }\n            .mulu-btn-sec:hover { color: #64748B; }\n\n            .mulu-body {\n                width: 64px;\n                height: 64px;\n                position: relative;\n                cursor: pointer;\n                pointer-events: auto;\n                transition: transform 0.2s ease;\n                filter: drop-shadow(0 6px 16px rgba(0, 0, 0, 0.15));\n            }\n\n            .mulu-body:hover {\n                transform: scale(1.1) translateY(-2px);\n            }\n\n            .mulu-img {\n                width: 100%;\n                height: 100%;\n                object-fit: contain;\n                animation: muluFloat 3.5s ease-in-out infinite;\n            }\n\n            .mulu-highlight {\n                outline: 3px solid #4FC3F7 !important;\n                outline-offset: 4px;\n                transition: outline 0.3s ease;\n            }\n\n            @keyframes muluFloat {\n                0%, 100% { transform: translateY(0px) rotate(0deg); }\n                50% { transform: translateY(-5px) rotate(2deg); }\n            }\n\n            @keyframes muluPop {\n                from { opacity: 0; transform: scale(0.85) translateY(6px); }\n                to { opacity: 1; transform: scale(1) translateY(0); }\n            }\n\n            @media (max-width: 640px) {\n                .mulu-floating-widget { bottom: 16px; right: 16px; }\n                .mulu-body { width: 52px; height: 52px; }\n                .mulu-bubble { max-width: 180px; font-size: 11px; }\n            }\n        ",document.head.appendChild(t)}render(){let t=document.getElementById("mulu-container");t||(t=document.createElement("div"),t.id="mulu-container",t.className="mulu-floating-widget",document.body.appendChild(t)),t.innerHTML='\n            <div class="mulu-bubble" id="mulu-speech">\n                <button class="mulu-close-btn" onclick="window.muluInstance.closeBubble()" title="Close">×</button>\n                <span id="mulu-text">Hi! I\'m Mulu, your STEMulus AI guide!</span>\n                <div class="mulu-tour-actions" id="mulu-actions" style="display:none;">\n                    <button class="mulu-btn-sec" onclick="window.muluInstance.skipTour()">Skip</button>\n                    <button class="mulu-btn" id="mulu-next-btn" onclick="window.muluInstance.nextTourStep()">Next →</button>\n                </div>\n            </div>\n            <div class="mulu-body" id="mulu-character" onclick="window.muluInstance.handleClick()">\n                <img src="images/portal/mulu_mascot_nobg.png" alt="Mulu Mascot" class="mulu-img" id="mulu-img">\n            </div>\n        '}bindEvents(){this.tips=["Need help? Check your scheduled classes on the dashboard!","Pro-Tip: Attendance logs can be submitted right after class!","Mulu is here to make STEM learning fun and smooth!","Click on any session card to view details!","Have feedback? Message your coordinator on WhatsApp!"],window.muluInstance=this}scheduleAutoHide(){clearTimeout(this.autoHideTimer),this.autoHideTimer=setTimeout(()=>{const t=document.getElementById("mulu-actions");t&&"flex"!==t.style.display&&this.closeBubble()},5e3)}closeBubble(){const t=document.getElementById("mulu-speech");t&&(t.style.display="none")}showBubble(){const t=document.getElementById("mulu-speech");t&&(t.style.display="block")}checkFirstTimeTour(){localStorage.getItem("mulu_tour_completed")||setTimeout(()=>{this.startTour()},800)}startTour(){this.currentStep=0,this.showStep(0)}showStep(t){if(t>=this.tourSteps.length)return void this.finishTour();this.showBubble();const n=this.tourSteps[t];document.getElementById("mulu-text").innerText=n.text,document.getElementById("mulu-actions").style.display="flex";const e=document.getElementById("mulu-next-btn");if(t===this.tourSteps.length-1?e.innerText="Got it!":e.innerText="Next →",document.querySelectorAll(".mulu-highlight").forEach(t=>t.classList.remove("mulu-highlight")),n.highlight){const t=document.querySelector(n.highlight);t&&t.classList.add("mulu-highlight")}}nextTourStep(){this.currentStep++,this.showStep(this.currentStep)}skipTour(){this.finishTour()}finishTour(){localStorage.setItem("mulu_tour_completed","true"),document.querySelectorAll(".mulu-highlight").forEach(t=>t.classList.remove("mulu-highlight")),document.getElementById("mulu-actions").style.display="none",document.getElementById("mulu-text").innerText="Tour complete! Click me anytime for tips.",this.scheduleAutoHide()}handleClick(){if("flex"===document.getElementById("mulu-actions").style.display)return void this.nextTourStep();this.showBubble();const t=document.getElementById("mulu-text"),n=document.getElementById("mulu-img"),e=this.tips[Math.floor(Math.random()*this.tips.length)];t.innerText=e,n.style.transform="scale(1.15) rotate(-5deg)",setTimeout(()=>{n.style.transform="none"},250),this.scheduleAutoHide()}}document.addEventListener("DOMContentLoaded",()=>{window.mulu||(window.mulu=new MuluMascot)});